    	{
    	    faad_fprintf(stderr, "Error opening file: %s\n", aacFileName);
    	    return 1;
    	}
    }

    fread(header, 1, 8, hMP4File);

    if (! readFromStdin )
      fclose(hMP4File);

    if (header[4] == 'f' && header[5] == 't' && header[6] == 'y' && header[7] == 'p')
        mp4file = 1;

